                    max = current;
                }
            }
            if (queue.size() < k) {
                queue.add(max);
            } else {
                if (queue.peek() < max) {
                    queue.poll();
                    queue.add(max);
                }
            }
            start++;
        }
        ArrayList<Integer> result = new ArrayList<>(k);
        while (!queue.isEmpty()) {
            result.add(queue.poll());
        }
