class Solution {
    public List<Integer> maximum(List<Integer> arr, int k) {
    // Find k elements of the maximum value
        // If a duplicate value exists, the following value must be unique.
        // This is the opposite of sorting by value.
        // All values in the array must be unique.
        // Time Complexity: O(k * log(k))
        ArrayList<Integer> new_arr = new ArrayList<Integer>();
        if (arr.size() < k) {
            return new_arr;
        }
        // Max heap
        PriorityQueue<Integer> pq = new PriorityQueue<Integer>(new Comparator<Integer>() {
            @Override
            public int compare(Integer o1, Integer o2) {
                if (o1 > o2) {
                    return -1;
                } else if (o1 < o2) {
                    return 1;
                } else {
                    return 0;
                }
            }
        });
        for (int i = 0; i < arr.size(); i++) {
            if (pq.size() < k) {
                pq.add(arr.get(i));
            } else {
                int top = pq.peek();
                if (top < arr.get(i)) {
                    pq.poll();
                    pq.add(arr.get(i));
                }
            }
        }
        while (!pq.isEmpty()) {
            new_arr.add(pq.poll());
        }
        return new_arr;

