            return -1;
        }
        HashMap<Integer, Integer> mp = new HashMap<Integer, Integer>();
        for (int num : lst) {
            mp.put(num, mp.getOrDefault(num, 0) + 1);
        }
        ArrayList<Pair<Integer, Integer>> pairs = new ArrayList<Pair<Integer, Integer>>();
        for (Map.Entry<Integer, Integer> entry : mp.entrySet()) {
            pairs.add(new Pair<Integer, Integer>(entry.getKey(), entry.getValue()));
        }
        Collections.sort(pairs, new PairComparator<Integer, Integer>());
        for (int i = 0; i < pairs.size(); i++) {
            if (pairs.get(i).a() >= pairs.get(i).b()) {
                return pairs.get(i).a();
            }
        }
        return -1;

