        // For each element in list
        for (int i = 0; i < numbers.size(); i++) {
            // Add element to result list
            rollingMaxs.add(numbers.get(i));
            // Check next elements in list and replace if found bigger number
            for (int j = i + 1; j < numbers.size(); j++) {
                if (numbers.get(j) > rollingMaxs.get(i)) {
                    rollingMaxs.set(i, numbers.get(j));
                }
            }
        }
