import java.util.*;
import java.lang.*;

class Solution {
    public List<Optional<Integer>> largestSmallestIntegers(List<Integer> lst){
    if (lst.size() < 1) {
            return new Pair<Optional<Integer>, Optional<Integer>>(Optional.empty(), Optional.empty());
        }

        var negatives = new ArrayList<Integer>();
        var positives = new ArrayList<Integer>();

        for (var value : lst) {
            if (value > 0) {
                positives.add(value);
            }
            else if (value < 0) {
                negatives.add(value);
            }
        }

        var answer = new Pair<Optional<Integer>, Optional<Integer>>(Optional.empty(), Optional.empty());

        if (negatives.size() > 0) {
            answer.setValue0(Optional.of(Collections.max(negatives)));
        }

        if (positives.size() > 0) {
            answer.setValue1(Optional.of(Collections.min(positives)));
        }

        return answer;

